import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { BOOK, UNITS, SEMESTERS, ACTIVITIES, BOOK_PAGES, COVERAGE } from './public/game/book-course.js';
import { evaluateActivity, normalizeAnswer, numberWithinTolerance, activityQuestions } from './public/game/course-progress.js';
import { plannedVariant } from './public/game/curriculum.js';

// The simplified mini-games are generated by scripts/build-minigames.mjs from the saved book activities.
const SOURCE = JSON.parse(readFileSync(new URL('./scripts/minigames/source/book-activities.json', import.meta.url), 'utf8'));
const TYPES = new Set(['match', 'quiz', 'reading', 'trivia', 'fill', 'order', 'grammar', 'listen', 'safety', 'colreg', 'math', 'science']);
const FORMATS = new Set(['choice', 'blank', 'scramble', 'number', 'sequence']);
const STEP_JOIN = ' | ';

assert.equal(BOOK_PAGES.length, 248);
assert.equal(UNITS.length, 10); assert.equal(SEMESTERS.length, 8);
assert.equal(ACTIVITIES.length, 381, 'All 381 book slots remain');
assert.deepEqual(ACTIVITIES.map(a => a.id), SOURCE.map(a => a.id), 'Slot ids and order are unchanged, so saved progress stays valid');
assert.equal(new Set(ACTIVITIES.map(a => a.id)).size, ACTIVITIES.length);
const questions = ACTIVITIES.flatMap(a => a.questions);
// Every playable set: the main set and each equivalent alternative.
const sets = ACTIVITIES.flatMap(a => [{ a, questions: a.questions }, ...(a.variants || []).map(v => ({ a, ...v }))]);
const playable = sets.flatMap(s => s.questions);
assert.equal(new Set(playable.map(q => q.id)).size, playable.length, 'Question ids are unique across every set');

for (const [i, a] of ACTIVITIES.entries()) {
  const original = SOURCE[i];
  for (const key of ['semester', 'year', 'term', 'unit', 'location', 'room']) assert.equal(a[key], original[key], `${a.id} keeps its ${key}`);
  assert.deepEqual(a.sourcePages, original.sourcePages, `${a.id} keeps its book pages`);
  assert.ok(a.required); assert.equal(a.year, Math.ceil(a.semester / 2));
  assert.ok(TYPES.has(a.type), `${a.id} has a simple game type (${a.type})`);
  assert.equal(a.reviewMode, 'exact');
  assert.ok(a.questions.length >= 4, `${a.id} has at least four questions`);
  for (const p of [...a.sourcePages, ...(a.studyPages || [])]) assert.ok(BOOK_PAGES[p - 1], `Missing source ${p}`);
  assert.ok(a.meta && a.meta.version >= 1 && a.meta.subject && a.meta.major && a.meta.difficulty && a.meta.host, `${a.id} has curriculum metadata`);
  assert.ok(Array.isArray(a.studyNotes) && a.studyNotes.length > 0, `${a.id} has study notes`);
  for (const v of a.variants || []) {
    assert.ok(['common', 'deck', 'engine'].includes(v.major), `${a.id} variant ${v.set} major`);
    assert.ok(v.questions.length >= 4, `${a.id} variant ${v.set} has at least four questions`);
    assert.notDeepEqual(v.questions.map(q => q.prompt), a.questions.map(q => q.prompt), `${a.id} variant ${v.set} is a different set`);
  }
  for (const q of sets.filter(s => s.a === a).flatMap(s => s.questions)) {
    assert.ok(q.prompt.trim(), q.id);
    assert.ok(FORMATS.has(q.format), `${q.id} format`);
    assert.ok(q.answers?.length && q.answers.every(x => typeof x === 'string' && x.trim()), `${q.id} is auto-checked`);
    assert.ok(!q.criteria, `${q.id} has no self-review criteria`);
    assert.ok(!/\[\d+ marks?\]/.test(q.prompt), `${q.id} prompt is tidy`);
    if (q.format === 'choice') {
      assert.ok(q.options.length >= 3 && q.options.length <= 4, `${q.id} has 3–4 options`);
      assert.equal(new Set(q.options.map(normalizeAnswer)).size, q.options.length, `${q.id} options are distinct`);
      assert.equal(q.options.filter(o => q.answers.some(x => normalizeAnswer(x) === normalizeAnswer(o))).length, 1, `${q.id} has exactly one correct option`);
    }
    if (q.format === 'scramble') {
      assert.deepEqual([...q.tokens].sort(), q.answers[0].split(/\s+/).sort(), `${q.id} tiles build the answer`);
      assert.notEqual(q.tokens.join(' '), q.answers[0], `${q.id} tiles start shuffled`);
    }
    if (q.format === 'sequence') {
      assert.deepEqual([...q.tokens].sort(), q.answers[0].split(STEP_JOIN).sort(), `${q.id} steps build the answer`);
      assert.notEqual(q.tokens.join(STEP_JOIN), q.answers[0], `${q.id} steps start shuffled`);
    }
    if (q.format === 'number') {
      assert.ok(Number.isFinite(q.value) && q.tolerance >= 0, `${q.id} has a value and tolerance`);
      assert.ok(numberWithinTolerance(q, String(q.value)) && numberWithinTolerance(q, `${q.value} ${q.unit || ''}`), `${q.id} accepts its value`);
      assert.ok(!numberWithinTolerance(q, String(q.value + q.tolerance + Math.max(1, Math.abs(q.value) * 0.1))), `${q.id} rejects a wrong number`);
    }
    if (q.figure) assert.ok(['gauge', 'lights'].includes(q.figure.kind), `${q.id} figure kind`);
  }
  // The correct answers pass the real evaluator; a wrong choice does not.
  const right = Object.fromEntries(a.questions.map(q => [q.id, q.answers[0]]));
  assert.equal(evaluateActivity(a, right).passed, true, `${a.id} passes with its answer key`);
  for (const [index, v] of (a.variants || []).entries()) {
    const played = { ...a, questions: activityQuestions(a, index) };
    assert.equal(played.questions, v.questions);
    assert.equal(evaluateActivity(played, Object.fromEntries(v.questions.map(q => [q.id, q.answers[0]]))).passed, true, `${a.id} variant ${v.set} passes with its key`);
  }
  // The planned set always fits the cadet's major.
  for (const major of ['deck', 'engine']) for (const journey of ['journey-a', 'journey-b', 'journey-c']) {
    const index = plannedVariant(a, journey, major);
    assert.ok(index === -1 || ['common', major].includes(a.variants[index].major), `${a.id} plans a ${major} set`);
  }
  const choiceQ = a.questions.find(q => q.format === 'choice');
  if (choiceQ) {
    const wrong = choiceQ.options.find(o => !choiceQ.answers.some(x => normalizeAnswer(x) === normalizeAnswer(o)));
    assert.equal(evaluateActivity(a, { ...right, [choiceQ.id]: wrong }).passed, false, `${a.id} rejects a wrong choice`);
  }
}

const locations = ['entrance', 'imd', 'cruise', 'pacific', 'workshop', 'dome', 'academic', 'garden', 'cafe', 'atlantic'];
for (const sem of SEMESTERS) {
  const assigned = ACTIVITIES.filter(a => a.semester === sem.id);
  assert.deepEqual(sem.activityIds, assigned.map(a => a.id));
  for (const id of locations) assert.ok(assigned.some(a => a.location === id), `Semester ${sem.id} missing ${id}`);
  for (const type of ['reading', 'match', 'order', 'grammar', 'math', 'safety', 'colreg']) assert.ok(assigned.some(a => a.type === type), `Semester ${sem.id} has a ${type} game`);
}
const counts = ACTIVITIES.reduce((m, a) => (m[a.type] = (m[a.type] || 0) + 1, m), {});
assert.ok(counts.science >= 8 && counts.math >= 20 && counts.colreg >= 20 && counts.safety >= 20 && counts.reading >= 50, 'Subject games are spread across the course');
for (const p of BOOK_PAGES) {
  assert.ok(existsSync(new URL('./public' + p.asset, import.meta.url)), `Missing page image ${p.page}`);
  if (p.page >= 9 && p.page <= 241 && ![212, 213].includes(p.page)) assert.ok(p.activityIds.length, `Unassigned instructional page ${p.page}`);
}
const finalItems = ACTIVITIES.flatMap(a => a.assessmentItemIds || []).sort((a, b) => a - b);
assert.deepEqual(finalItems, Array.from({ length: 154 }, (_, i) => i + 1));
assert.equal(ACTIVITIES.flatMap(a => a.pairs || []).length, 162);
const pdf = readFileSync(new URL('./public' + BOOK.pdfUrl, import.meta.url));
assert.equal(createHash('sha256').update(pdf).digest('hex'), BOOK.sourceSha256);
assert.equal(COVERAGE.counts.questions, questions.length);
assert.equal(COVERAGE.counts.selfReviewQuestions, 0);
assert.equal(COVERAGE.counts.playableQuestions, playable.length);
console.log('Mini-game checks passed:', { games: ACTIVITIES.length, questions: questions.length, playable: playable.length, alternativeSets: sets.length - ACTIVITIES.length, types: counts,
  formats: playable.reduce((m, q) => (m[q.format] = (m[q.format] || 0) + 1, m), {}) });
